#!/usr/bin/env node
/**
 * codegen-validator.js — Generates src/lib/generated/validation-rules.js from parameter-schema-v2.json
 *
 * The generated file exports validation functions per parameter.
 * Currently used for parity checking against config-manager.js validation logic.
 * In Phase 3, config-manager.js will import these directly.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');

const schema = JSON.parse(fs.readFileSync(path.join(ROOT, 'config', 'parameter-schema-v2.json'), 'utf8'));
const outDir = path.join(ROOT, 'src', 'lib', 'generated');
fs.mkdirSync(outDir, { recursive: true });

const lines = [
    '// AUTO-GENERATED by scripts/codegen-validator.js — DO NOT EDIT',
    '// Source: config/parameter-schema-v2.json',
    `// Generated: ${new Date().toISOString()}`,
    '',
    '/**',
    ' * Validation rules derived from parameter-schema-v2.json.',
    ' * Each key maps to a function that returns null (valid) or an error string.',
    ' */',
    'export const validationRules = {'
];

let count = 0;
for (const [key, param] of Object.entries(schema.parameters)) {
    const v = param.validation;
    if (!v || Object.keys(v).length === 0) continue;

    const checks = [];

    if (v.enum) {
        checks.push(`if (!${JSON.stringify(v.enum)}.includes(value)) return \`Invalid value "\${value}" for ${key}. Valid: ${v.enum.join(', ')}\``);
    }
    if (v.min !== undefined) {
        checks.push(`if (value < ${v.min}) return \`${key} must be >= ${v.min}, got \${value}\``);
    }
    if (v.max !== undefined) {
        checks.push(`if (value > ${v.max}) return \`${key} must be <= ${v.max}, got \${value}\``);
    }
    if (v.minLength !== undefined) {
        checks.push(`if (value.length < ${v.minLength}) return \`${key} must be at least ${v.minLength} characters\``);
    }
    if (v.maxLength !== undefined) {
        checks.push(`if (value.length > ${v.maxLength}) return \`${key} must be at most ${v.maxLength} characters\``);
    }
    if (v.pattern) {
        // Use RegExp constructor to avoid issues with slashes in patterns
        checks.push(`if (!new RegExp(${JSON.stringify(v.pattern)}).test(value)) return \`${key} does not match required pattern\``);
    }

    if (checks.length === 0) continue;

    lines.push(`    ${JSON.stringify(key)}: (value) => {`);
    checks.forEach(c => lines.push(`        ${c};`));
    lines.push('        return null;');
    lines.push('    },');
    count++;
}

lines.push('};');
lines.push('');
lines.push(`// ${count} parameters have validation rules`);
lines.push('');

fs.writeFileSync(path.join(outDir, 'validation-rules.js'), lines.join('\n'));
console.log(`✅ Generated src/lib/generated/validation-rules.js (${count} validators)`);
